"""Local simulator to check estimator coverage / width before dry_run."""
import random, sys, importlib
sys.path.insert(0, "/app")
import estimator

TOPICS = ["code", "math", "writing", "factual"]
LENGTHS = ["short", "long"]
# guessed true win rates per stratum (from judge means) and judge error rates
T = {("code", "long"): 0.45, ("code", "short"): 0.35, ("factual", "long"): 0.8,
     ("factual", "short"): 0.44, ("math", "long"): 0.25, ("math", "short"): 0.38,
     ("writing", "long"): 0.47, ("writing", "short"): 0.3}


def make_rates(scale):
    fpr = {("code", "long"): 0.08, ("math", "long"): 0.10, ("factual", "short"): 0.03}
    fnr = {("math", "short"): 0.15, ("writing", "short"): 0.12}
    out = {}
    for t in TOPICS:
        for l in LENGTHS:
            out[(t, l)] = (min(0.6, scale * fpr.get((t, l), 0.01)), min(0.6, scale * fnr.get((t, l), 0.01)))
    return out


class Env:
    def __init__(self, rng, rates, n=900, budget=220, jitter=0.0):
        self.rng = rng
        shares = [rng.gammavariate(3, 1) for _ in range(8)]
        s = sum(shares); shares = [x / s for x in shares]
        strata = [(t, l) for t in TOPICS for l in LENGTHS]
        self.rows, self.truth = [], {}
        i = 0
        for st, sh in zip(strata, shares):
            k = max(30, int(round(n * sh)))
            fpr, fnr = rates[st]
            tt = min(0.95, max(0.05, T[st] + rng.gauss(0, jitter)))
            for _ in range(k):
                h = rng.random() < tt
                j = (rng.random() >= fnr) if h else (rng.random() < fpr)
                self.rows.append({"id": i, "topic": st[0], "length": st[1], "judge_win": j})
                self.truth[i] = h
                i += 1
        mixw = [rng.gammavariate(1.5, 1) for _ in range(8)]
        s = sum(mixw)
        self.production_mix = {"%s|%s" % st: w / s for st, w in zip(strata, mixw)}
        self.label_budget = budget
        self.topics, self.lengths = TOPICS, LENGTHS
        self.target_coverage = 0.9
        self.spent = 0
        self.result = None
        # true production-mix win rate (finite population)
        by = {}
        for r in self.rows:
            by.setdefault((r["topic"], r["length"]), []).append(self.truth[r["id"]])
        self.true_rate = sum(self.production_mix["%s|%s" % st] * (sum(v) / len(v)) for st, v in by.items())

    def label(self, ids):
        self.spent += len(ids)
        assert self.spent <= self.label_budget, "budget exceeded"
        return {str(i): self.truth[i] for i in ids}

    def submit(self, p, lo, hi):
        self.result = (p, lo, hi)


def run(scale=1.0, jitter=0.0, reps=60, seed=0):
    rng = random.Random(seed)
    rates = make_rates(scale)
    cov, widths, errs = 0, [], []
    for _ in range(reps):
        env = Env(rng, rates, jitter=jitter)
        estimator.estimate(env)
        p, lo, hi = env.result
        cov += lo <= env.true_rate <= hi
        widths.append(hi - lo)
        errs.append(p - env.true_rate)
    print("scale=%.1f jitter=%.2f coverage=%.2f mean width=%.4f mean|err|=%.4f max width=%.4f" % (
        scale, jitter, cov / reps, sum(widths) / reps, sum(abs(e) for e in errs) / reps, max(widths)))


if __name__ == "__main__":
    for scale, jitter in [(1.0, 0.0), (1.0, 0.1), (2.0, 0.1), (3.0, 0.1), (0.3, 0.1)]:
        run(scale, jitter)

